import random
import sympy

GROUP = "number_theory"
SKILL = "invariant"

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(30, 50)

    # Define a function to check if a number is prime using the invariant property
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    # Count the number of primes in the range using the invariant property
    answer = sum(1 for num in range(1, n + 1) if is_prime(num))

    # Independent route: Verify the count by explicitly checking each number for primality.
    check = 0
    for num in range(1, n + 1):
        if is_prime(num):
            check += 1
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"How many prime numbers k with 1 <= k <= {n} are there? State only the integer.\n"
        f"The problem asks for the count of prime numbers in the range from 1 to {n}.\n"
        f"Numbers in the range are: {list(range(1, n + 1))}"
    )

    return problem, str(answer)

import random

GROUP = "number_theory"
SKILL = "construction"

def count_integers(n, k):
    integers = [0] * (k + 1)
    integers[0] = 1

    for i in range(1, n + 1):
        for j in range(min(i, k), 0, -1):
            integers[j] += integers[j - 1]

    return integers[k]

def generate(seed):
    rng = random.Random(seed)

    n = rng.randint(3000, 40000)
    k = rng.randint(2, n - 1)

    # Find the threshold k for which the subset can be formed
    for i in range(2, k + 1):
        if count_integers(n, i) > 0:
            threshold_k = i
            break

    # Independent route: Iterate from the minimum k to find the smallest k that can form a valid subset.
    check_k = 2
    while True:
        if count_integers(n, check_k) > 0:
            break
        check_k += 1

    assert threshold_k == check_k, f"threshold_k={threshold_k} check_k={check_k}"

    problem = (
        f"Determine the smallest size of integers to be chosen from the range 1 to {n} such that a subset of {threshold_k} integers can be formed where each integer is unique and all integers sum to exactly {threshold_k}. State only the integer."
    )
    return problem, str(threshold_k)

