GROUP = "combinatorics"
SKILL = "induction"


def max_partition_sizes(max_n, min_sum, max_sum, target_sum):
    if target_sum == 0:
        return 0

    if target_sum < min_sum:
        return -1

    max_count = 0

    for part_sum in range(min_sum, max_sum + 1):
        if part_sum <= target_sum:
            remaining_sum = target_sum - part_sum
            count = max_partition_sizes(max_n, min_sum, part_sum - 1, remaining_sum)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    max_n = rng.randint(5, 15)
    min_sum = rng.randint(10, 30)
    max_sum = rng.randint(50, 80)
    target_sum = rng.randint(60, 120)

    answer = max_partition_sizes(max_n, min_sum, max_sum, target_sum)

    check = -1
    for part_sum in range(min_sum, max_sum + 1):
        if part_sum <= target_sum:
            remaining_sum = target_sum - part_sum
            count = max_partition_sizes(max_n, min_sum, part_sum - 1, remaining_sum)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a set of integers with maximum value {max_n}. Partition the set into subsets such that the sum of their sizes ranges from {min_sum} to {max_sum} (inclusive). "
        f"What is the maximum number of distinct subsets that can be formed such that no subset sum exceeds the target sum {target_sum} and all subset sums sum to exactly {target_sum}? State only the integer."
    )
    return problem, str(answer)

