def find_max_terms(target, min_terms, max_terms):
    if target == 0:
        return 0

    if target < min_terms:
        return -1

    max_count = 0

    for terms in range(min_terms, max_terms + 1):
        if terms <= target:
            remaining_target = target - terms
            count = find_max_terms(remaining_target, min_terms, terms - 1)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    min_terms = rng.randint(2, 5)
    max_terms = rng.randint(7, 12)
    target_value = rng.randint(10, 20)

    answer = find_max_terms(target_value, min_terms, max_terms)

    check = -1
    for terms in range(min_terms, max_terms + 1):
        if terms <= target_value:
            remaining_target = target_value - terms
            count = find_max_terms(remaining_target, min_terms, terms - 1)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a sequence of integers where the sum of any subset of terms ranges from {min_terms} to {max_terms} (inclusive). "
        f"What is the maximum number of distinct terms that can be selected such that no subset sum exceeds the target terms {target_value} and all subset sums sum to exactly {target_value}? State only the integer."
    )
    return problem, str(answer)

import random

GROUP = "algebra"
SKILL = "casework"


def generate(seed):
    rng = random.Random(seed)
    degree = rng.randint(1, 4)
    coefficients = sorted(rng.sample(range(-10, 11), degree + 1))

    # Generate a polynomial with random coefficients
    def polynomial(x):
        return sum(coeff * (x ** i) for i, coeff in enumerate(coefficients))

    # Calculate the number of distinct roots of the polynomial in the range -10 to 10 inclusive
    roots = {x for x in range(-10, 11) if polynomial(x) == 0}
    answer = len(roots)

    # Independent route: Verify the answer by checking the number of distinct roots
    check_roots = {x for x in range(-10, 11) if polynomial(x) == 0}
    assert answer == len(check_roots), f"answer={answer} check={len(check_roots)}"

    problem = (
        f"How many distinct values of x in the range -10 to 10 inclusive are roots of the polynomial "
        f"p(x) = {coefficients[-1]}x^{degree} + {coefficients[-2]}x^{degree - 1} + ... + {coefficients[0]}? State only the integer.\n"
        f"The polynomial is p(x) = {coefficients[-1]}x^{degree} + {coefficients[-2]}x^{degree - 1} + ... + {coefficients[0]}.\n"
        f"The problem asks for the count of distinct x values in the range -10 to 10 inclusive that are roots of the polynomial."
    )

    return problem, str(answer)

