def max_square_areas(grid_size, min_area_sum, max_area_sum, target_area):
    if target_area == 0:
        return 0

    if target_area < min_area_sum:
        return -1

    max_count = 0

    for area_sum in range(min_area_sum, max_area_sum + 1):
        if area_sum <= target_area:
            remaining_area = target_area - area_sum
            count = max_square_areas(grid_size, min_area_sum, area_sum - 1, remaining_area)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    grid_size = rng.randint(10, 20)
    min_area_sum = rng.randint(10, 30)
    max_area_sum = rng.randint(50, 80)
    target_area = rng.randint(60, 120)

    answer = max_square_areas(grid_size, min_area_sum, max_area_sum, target_area)

    check = -1
    for area_sum in range(min_area_sum, max_area_sum + 1):
        if area_sum <= target_area:
            remaining_area = target_area - area_sum
            count = max_square_areas(grid_size, min_area_sum, area_sum - 1, remaining_area)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a square grid with side length {grid_size}. Select squares such that the sum of their areas ranges from {min_area_sum} to {max_area_sum} (inclusive). "
        f"What is the maximum number of distinct squares that can be selected such that no subset sum exceeds the target sum {target_area} and all subset sums sum to exactly {target_area}? State only the integer."
